// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface IUniswapV3Factory {
    function getPool(address tokenA, address tokenB, uint24 fee) external view returns (address);
}

interface IUniswapV3Pool {
    function slot0()
        external
        view
        returns (
            uint160 sqrtPriceX96,
            int24 tick,
            uint16 observationIndex,
            uint16 observationCardinality,
            uint16 observationCardinalityNext,
            uint8 feeProtocol,
            bool unlocked
        );
}

interface ISwapRouter02 {
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    function exactInputSingle(ExactInputSingleParams calldata params) external payable returns (uint256 amountOut);
}

interface INonfungiblePositionManager {
    struct MintParams {
        address token0;
        address token1;
        uint24 fee;
        int24 tickLower;
        int24 tickUpper;
        uint256 amount0Desired;
        uint256 amount1Desired;
        uint256 amount0Min;
        uint256 amount1Min;
        address recipient;
        uint256 deadline;
    }

    struct IncreaseLiquidityParams {
        uint256 tokenId;
        uint256 amount0Desired;
        uint256 amount1Desired;
        uint256 amount0Min;
        uint256 amount1Min;
        uint256 deadline;
    }

    function mint(MintParams calldata params)
        external
        payable
        returns (uint256 tokenId, uint128 liquidity, uint256 amount0, uint256 amount1);

    function increaseLiquidity(IncreaseLiquidityParams calldata params)
        external
        payable
        returns (uint128 liquidity, uint256 amount0, uint256 amount1);
}

/// @title Rebalancer
/// @notice Deploys a skewed WETH/USDC purse into a single tight Uniswap v3 position.
///         Strategy: mint with whatever we have (discovers the exact token ratio the
///         range wants at the live price), then iteratively swap the surplus side into
///         the deficit side using that ratio and top up the position with increaseLiquidity.
contract Rebalancer {
    address public constant WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2; // token1
    address public constant USDC = 0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48; // token0
    address public constant ROUTER = 0x68b3465833fb72A70ecDF485E0e4C7bD8665Fc45;
    address public constant NPM = 0xC36442b4a4522E871399CD717aBDD847Ab11FE88;
    address public constant FACTORY = 0x1F98431c8aD98523631AE4a59f267346ea31F984;

    uint24 public constant FEE = 3000; // tick spacing 60

    // Current tick 200808. Lower is 168 ticks below (~1.69%), upper is 132 ticks above (~1.33%).
    // Both are multiples of 60 and both sit inside the [1%, 2.5%] band.
    int24 public constant TICK_LOWER = 200640;
    int24 public constant TICK_UPPER = 200940;

    uint256 public tokenId;

    function provide() external {
        require(tokenId == 0, "already provided");

        IERC20(WETH).approve(ROUTER, type(uint256).max);
        IERC20(USDC).approve(ROUTER, type(uint256).max);
        IERC20(WETH).approve(NPM, type(uint256).max);
        IERC20(USDC).approve(NPM, type(uint256).max);

        address pool = IUniswapV3Factory(FACTORY).getPool(USDC, WETH, FEE);
        require(pool != address(0), "no pool");

        // 1. Initial mint: consumes all of the scarce side (USDC) and a matching slice of WETH.
        //    The consumed amounts give us the exact token0:token1 ratio the range needs right now.
        (uint256 id, , uint256 used0, uint256 used1) = INonfungiblePositionManager(NPM).mint(
            INonfungiblePositionManager.MintParams({
                token0: USDC,
                token1: WETH,
                fee: FEE,
                tickLower: TICK_LOWER,
                tickUpper: TICK_UPPER,
                amount0Desired: _bal(USDC),
                amount1Desired: _bal(WETH),
                amount0Min: 0,
                amount1Min: 0,
                recipient: address(this),
                deadline: block.timestamp
            })
        );
        tokenId = id;

        // 2. Rebalance leftovers toward the discovered ratio and top the position up.
        //    A few passes absorb swap fees / price impact from the previous pass.
        for (uint256 i = 0; i < 4; i++) {
            if (used0 == 0 || used1 == 0) break;

            uint256 b0 = _bal(USDC);
            uint256 b1 = _bal(WETH);
            (uint160 sqrtP, , , , , , ) = IUniswapV3Pool(pool).slot0();

            if (b1 * used0 > b0 * used1) {
                // Surplus WETH. Solve (b0 + x*px) * used1 == (b1 - x) * used0 for x (in WETH wei).
                uint256 x = (b1 * used0 - b0 * used1) / (used0 + _usdcValue(used1, sqrtP));
                if (x < 5e14) break; // ~$1 of WETH, not worth a swap
                _swap(WETH, USDC, x, (_usdcValue(x, sqrtP) * 95) / 100);
            } else {
                // Surplus USDC. Solve (b0 - y) * used1 == (b1 + y/px) * used0 for y (in USDC units).
                uint256 y = (b0 * used1 - b1 * used0) / (used1 + _wethValue(used0, sqrtP));
                if (y < 1e6) break; // < 1 USDC
                _swap(USDC, WETH, y, (_wethValue(y, sqrtP) * 95) / 100);
            }

            b0 = _bal(USDC);
            b1 = _bal(WETH);
            if (b0 == 0 || b1 == 0) break;

            (, used0, used1) = INonfungiblePositionManager(NPM).increaseLiquidity(
                INonfungiblePositionManager.IncreaseLiquidityParams({
                    tokenId: id,
                    amount0Desired: b0,
                    amount1Desired: b1,
                    amount0Min: 0,
                    amount1Min: 0,
                    deadline: block.timestamp
                })
            );
        }
    }

    function onERC721Received(address, address, uint256, bytes calldata) external pure returns (bytes4) {
        return this.onERC721Received.selector;
    }

    // ---------------------------------------------------------------- internals

    function _bal(address token) internal view returns (uint256) {
        return IERC20(token).balanceOf(address(this));
    }

    function _swap(address tokenIn, address tokenOut, uint256 amountIn, uint256 minOut) internal {
        ISwapRouter02(ROUTER).exactInputSingle(
            ISwapRouter02.ExactInputSingleParams({
                tokenIn: tokenIn,
                tokenOut: tokenOut,
                fee: FEE,
                recipient: address(this),
                amountIn: amountIn,
                amountOutMinimum: minOut,
                sqrtPriceLimitX96: 0
            })
        );
    }

    /// @dev USDC (token0) value of a WETH (token1) amount at the pool's spot sqrt price.
    ///      price = sqrtP^2 / 2^192 is token1 per token0, so token0 = token1 * 2^192 / sqrtP^2.
    function _usdcValue(uint256 wethAmount, uint160 sqrtP) internal pure returns (uint256) {
        uint256 v = (wethAmount << 96) / sqrtP;
        return (v << 96) / sqrtP;
    }

    /// @dev WETH (token1) value of a USDC (token0) amount at the pool's spot sqrt price.
    function _wethValue(uint256 usdcAmount, uint160 sqrtP) internal pure returns (uint256) {
        uint256 v = (usdcAmount * sqrtP) >> 96;
        return (v * sqrtP) >> 96;
    }
}
